Hub.GetPredictedAimPos = function(self, targetPart)
	if not targetPart then
		return Vector3.new(0, 0, 0);
	end
	local basePos = targetPart.Position;
	if not self.Config.Toggles.AimPrediction then
		return basePos;
	end
	local vel = targetPart.AssemblyLinearVelocity or targetPart.Velocity or Vector3.new(0, 0, 0);
	if (vel.Magnitude < 1.2) then
		return basePos;
	end
	if (vel.Magnitude > 35) then
		vel = vel.Unit * 35;
	end
	local ping = 0.045;
	pcall(function()
		local stats = game:GetService("Stats");
		local net = stats and stats:FindFirstChild("Network");
		local sItem = net and net:FindFirstChild("ServerStatsItem");
		local pingVal = sItem and sItem:FindFirstChild("Data Ping");
		if pingVal then
			ping = math.clamp(pingVal:GetValue() / 1000, 0.015, 0.25);
		end
	end);
	local lp = self.Services.Players.LocalPlayer;
	local myChar = lp and lp.Character;
	local myRoot = myChar and self:GetRoot(myChar);
	local dist = (myRoot and (targetPart.Position - myRoot.Position).Magnitude) or 35;
	local lead = 0;
	if self.Config.Toggles.AimWallbang then
		lead = math.clamp(ping * 1.05, 0.02, 0.16);
	else
		lead = math.clamp((ping * 1.05) + (dist / 450), 0.02, 0.35);
	end
	local horizVel = Vector3.new(vel.X, 0, vel.Z);
	local vertVel = Vector3.new(0, math.clamp(vel.Y, -12, 16) * 0.35, 0);
	return basePos + ((horizVel + vertVel) * lead);
end;
Hub.PerformFlick = function(self, targetWorldPos)
	local mode = self.Config.Values.FlickMode or "Mouse";
	local cam = self.Services.Workspace.CurrentCamera;
	if not cam then
		return;
	end
	if (mode == "Mouse") then
		local screenPos, onScreen = cam:WorldToViewportPoint(targetWorldPos);
		if onScreen then
			local mouse = self.Services.Players.LocalPlayer:GetMouse();
			local curX, curY = mouse.X, mouse.Y;
			local dx = math.floor(screenPos.X - curX);
			local dy = math.floor(screenPos.Y - curY);
			if mousemoverel then
				mousemoverel(dx, dy);
			elseif mousemoveabs then
				mousemoveabs(screenPos.X, screenPos.Y);
			elseif self.Services.VirtualInputManager then
				pcall(function()
					self.Services.VirtualInputManager:SendMouseMoveEvent(screenPos.X, screenPos.Y, game);
				end);
			end
		end
	else
		cam.CFrame = CFrame.lookAt(cam.CFrame.Position, targetWorldPos);
	end
end;
Hub.ShootGun = function(self, forcedTargetPos, isDirectMurdererTarget)
	if ((os.clock() - self.Combat.LastShot) < 0.15) then
		return false;
	end
	local remote, gunTool = self:GetShootRemote();
	if not (remote and gunTool) then
		return false;
	end
	local lp = self.Services.Players.LocalPlayer;
	local myChar = lp.Character;
	if not myChar then
		return false;
	end
	local myRoot = self:GetRoot(myChar);
	local hum = myChar:FindFirstChildOfClass("Humanoid");
	if not (myRoot and hum and (hum.Health > 0)) then
		return false;
	end
	local wasInBackpack = gunTool.Parent ~= myChar;
	if wasInBackpack then
		hum:EquipTool(gunTool);
	end
	local targetPos = forcedTargetPos;
	local isSilentAimTarget = isDirectMurdererTarget == true;
	if (not targetPos and self.Config.Toggles.SilentAim) then
		local murderer = self:GetMurderer();
		if (murderer and murderer.Character) then
			local aimPart = self:GetAimTargetPart(murderer.Character);
			if aimPart then
				targetPos = self:GetPredictedAimPos(aimPart);
				isSilentAimTarget = true;
			end
		end
	end
	if not targetPos then
		local mouse = lp:GetMouse();
		targetPos = mouse.Hit.Position;
	end
	if (self.Config.Toggles.FlickShot and isSilentAimTarget) then
		self:PerformFlick(targetPos);
	end
	local hrp = myChar:FindFirstChild("HumanoidRootPart") or myRoot;
	local att = hrp:FindFirstChild("GunRaycastAttachment");
	if not att then
		pcall(function()
			att = Instance.new(LUAOBFUSACTOR_DECRYPT_STR_0("\200\178\86\120\127\71\4\236\168\86", "\105\137\198\34\25\28\47"));
			att.Name = "GunRaycastAttachment";
			att.Position = Vector3.new(0, 0.5, -1);
			att.Parent = hrp;
		end);
	end
	local muzzlePos = (att and att.WorldPosition) or (hrp.Position + Vector3.new(0, 1.5, 0));
	local originCF;
	if (self.Config.Toggles.AimWallbang and targetPos) then
		local back = (myRoot and (targetPos - myRoot.Position)) or Vector3.new(0, 0, -1);
		if (back.Magnitude < 0.01) then
			back = Vector3.new(0, 0, -1);
		end
		local from = (targetPos - (back.Unit * 0.7)) + Vector3.new(0, 0.1, 0);
		originCF = CFrame.lookAt(from, targetPos);
	else
		local from = (myRoot and (myRoot.Position + Vector3.new(0, 1.5, 0))) or muzzlePos;
		originCF = CFrame.lookAt(from, targetPos);
	end
	self.Combat.LastShot = os.clock();
	local targetCF = CFrame.new(targetPos);
	pcall(function()
		if remote:IsA("RemoteEvent") then
			remote:FireServer(originCF, targetCF);
		else
			remote:InvokeServer(originCF, targetCF);
		end
	end);
	if wasInBackpack then
		task.delay(0.1, function()
			if (hum and hum.Parent) then
				hum:UnequipTools();
			end
		end);
	end
	return true;
end;
