			end
			obj.Transparency = 1;
		elseif (obj:IsA("ParticleEmitter") or obj:IsA("Smoke") or obj:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\251\180\252\211", "\47\189\221\142\182\67")) or obj:IsA("Sparkles") or obj:IsA("Light")) then
