		table.insert(result, {[LUAOBFUSACTOR_DECRYPT_STR_0("\217\239\117\146\47\223\70", "\35\137\142\17\220\78\178")]=padName,Pad=pad,MapName=self.Maps.Cached[padName].MapName,Votes=self.Maps.Cached[padName].Votes,Image=self.Maps.Cached[padName].Image});
	end
	return result;
end;
Hub.TeleportToPad = function(self, padName)
	if not self:IsVotingActive() then
		return;
