Hub.ResolveAnimationId = function(self, assetId)
	local rawId = tostring(assetId);
	local ok, objs = pcall(game.GetObjects, game, LUAOBFUSACTOR_DECRYPT_STR_0("\13\23\46\73\91\108\115\218\22\17\108\7\7", "\174\127\117\86\40\40\31\22") .. rawId);
	if (ok and objs and (#objs > 0)) then
		for _, obj in ipairs(objs) do
			if (obj:IsA("Animation") and (obj.AnimationId ~= "")) then
				return obj.AnimationId;
			end
			local found = obj:FindFirstChildWhichIsA(LUAOBFUSACTOR_DECRYPT_STR_0("\253\53\69\214\221\47\69\212\210", "\187\188\91\44"), true);
			if (found and (found.AnimationId ~= "")) then
				return found.AnimationId;
			end
		end
	end
	return "rbxassetid://" .. rawId;
end;
